/* Does the map do what the verifier assumed, and refuse what it must?
 *
 * PREVAIL proves the program passed a map descriptor and reads at most
 * value_size bytes of what lookup returned. It cannot prove the HOST resolves an
 * index to a map of that shape, nor that the bounds callback is right. Both are
 * ours, and both are asserted here.
 *
 * The refusals matter more than the successes. A descriptor we cannot honour must
 * be REFUSED rather than clamped -- clamping would leave the verifier having
 * proved bounds for a shape we do not enforce, which is the exact failure O14
 * exists to prevent one level down.
 */
#include <assert.h>
#include <stdio.h>
#include "ls_map.h"

int
main(void)
{
    static struct ls_map_set S;
    struct ls_map_def d = { LS_MAP_TYPE_HASH, 4, 8, 64, 0 };
    struct ls_map *m;
    int n = 0, idx;

    /* 1. a descriptor we can honour */
    idx = ls_map_create(&S, &d);
    assert(idx == 0);                                                        n++;
    m = ls_map_get(&S, 0);
    assert(m && m->key_sz == 4 && m->val_sz == 8 && m->entries == 64);       n++;

    /* 2. REFUSALS. Each is a shape PREVAIL might verify against but we cannot
     *    store, so each must be rejected rather than trimmed to fit. */
    { struct ls_map_def b = { 99, 4, 8, 64, 0 };                  /* wrong type */
      assert(ls_map_create(&S, &b) < 0);                                     n++; }
    { struct ls_map_def b = { LS_MAP_TYPE_HASH, 99, 8, 64, 0 };   /* key too big */
      assert(ls_map_create(&S, &b) < 0);                                     n++; }
    { struct ls_map_def b = { LS_MAP_TYPE_HASH, 4, 999, 64, 0 };  /* val too big */
      assert(ls_map_create(&S, &b) < 0);                                     n++; }
    { struct ls_map_def b = { LS_MAP_TYPE_HASH, 4, 8, 99999, 0 }; /* too many   */
      assert(ls_map_create(&S, &b) < 0);                                     n++; }
    { struct ls_map_def b = { LS_MAP_TYPE_HASH, 0, 8, 64, 0 };    /* zero key   */
      assert(ls_map_create(&S, &b) < 0);                                     n++; }

    /* 3. THE VALIDATION: an index a program could hand back. No pointer is ever
     *    involved, so this is the whole of it. */
    assert(ls_map_get(&S, 1) == 0);          /* not created */                n++;
    assert(ls_map_get(&S, 4) == 0);          /* past LS_MAP_MAX */            n++;
    assert(ls_map_get(&S, 0xdeadbeefULL) == 0);  /* garbage */                n++;

    /* 4. store and retrieve */
    {
        uint32_t k = 0x1234; uint64_t v = 42, *got;
        assert(ls_map_update(m, (uint8_t *)&k, (uint8_t *)&v) == 0);          n++;
        got = ls_map_lookup(m, (uint8_t *)&k);
        assert(got && *got == 42);                                           n++;
    }

    /* 5. a miss is a miss, not a stale hit */
    {
        uint32_t k = 0x9999;
        assert(ls_map_lookup(m, (uint8_t *)&k) == 0);                         n++;
    }

    /* 6. accumulate across calls --- the whole reason this exists */
    {
        uint32_t k = 7; uint64_t one = 1, *v; int i;
        ls_map_update(m, (uint8_t *)&k, (uint8_t *)&one);
        for (i = 0; i < 39; i++) {
            v = ls_map_lookup(m, (uint8_t *)&k);
            assert(v);
            { uint64_t nv = *v + 1; ls_map_update(m, (uint8_t *)&k, (uint8_t *)&nv); }
        }
        v = ls_map_lookup(m, (uint8_t *)&k);
        assert(v && *v == 40);   /* "this key, forty times" */                n++;
    }

    /* 7. full table EVICTS and counts --- never blocks, never fails */
    {
        uint64_t before = m->evictions;
        uint32_t k; uint64_t v = 1;
        for (k = 1000; k < 1000 + 300; k++) {
            assert(ls_map_update(m, (uint8_t *)&k, (uint8_t *)&v) == 0);
        }
        n++;
        assert(m->evictions > before);   /* loss is visible */                n++;
    }

    /* 8. THE BOUNDS CALLBACK. uBPF permits only ctx and stack; this is what
     *    extends it to map values, and the JIT does not bounds-check at all --
     *    so getting this wrong makes the interpreter and the JIT disagree. */
    {
        uint64_t base = (uint64_t)(uintptr_t)m->vals;
        assert(ls_map_addr_ok(&S, base, 8));                                 n++;
        assert(ls_map_addr_ok(&S, base + LS_MAP_VAL_MAX, 8));                n++;
        /* keys and metadata are the host's --- never legal */
        assert(!ls_map_addr_ok(&S, (uint64_t)(uintptr_t)m->keys, 4));         n++;
        assert(!ls_map_addr_ok(&S, (uint64_t)(uintptr_t)m, 4));               n++;
        /* must not straddle into the next slot */
        assert(!ls_map_addr_ok(&S, base + LS_MAP_VAL_MAX - 4, 8));           n++;
        /* nor run off the end of the array */
        assert(!ls_map_addr_ok(&S,
               base + (uint64_t)m->entries * LS_MAP_VAL_MAX - 4, 8));        n++;
        /* nor be somewhere else entirely */
        assert(!ls_map_addr_ok(&S, 0, 8));                                    n++;
        assert(!ls_map_addr_ok(&S, 0xdeadbeef, 8));                           n++;
    }

    /* Every admitted capacity, including non-powers of two. Fill, delete holes,
     * update surviving collision chains, and refill without losing any key. */
    for (uint32_t capacity = 1; capacity <= LS_MAP_ENTRIES; capacity++) {
        memset(&S, 0, sizeof S);
        d.max_entries = capacity;
        assert(ls_map_create(&S, &d) == 0);
        m = ls_map_get(&S, 0);
        for (uint32_t key = 0; key < capacity; key++) {
            uint64_t value = key + 1000;
            assert(!ls_map_update(m, (uint8_t *)&key, (uint8_t *)&value));
        }
        for (uint32_t key = 0; key < capacity; key++) {
            uint64_t *value = ls_map_lookup(m, (uint8_t *)&key);
            assert(value && *value == key + 1000);
            if (!(key & 1)) assert(!ls_map_delete(m, (uint8_t *)&key));
        }
        for (uint32_t key = 1; key < capacity; key += 2) {
            uint64_t value = key + 2000;
            assert(!ls_map_update(m, (uint8_t *)&key, (uint8_t *)&value));
        }
        for (uint32_t key = 0; key < capacity; key += 2) {
            uint64_t value = key + 2000;
            assert(!ls_map_update(m, (uint8_t *)&key, (uint8_t *)&value));
        }
        for (uint32_t key = 0; key < capacity; key++) {
            uint64_t *value = ls_map_lookup(m, (uint8_t *)&key);
            assert(value && *value == key + 2000);
        }
        assert(m->evictions == 0);
    }
    puts("ok    all 256 map capacities: fill, delete, collision-chain update, refill");
    printf("ok    ls_map.h  (%d assertions: bad descriptors refused, index "
           "validated, accumulation, evict-and-count, bounds callback)\n", n);
    return 0;
}

/* Regression for output-map -> revoke -> hash-map storage reuse.
 * Cached pre-fix executions returned 1. Corrected hosts must return zero. */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"
#include <assert.h>

int main(void)
{
    struct ls_map_def output = {4, 4, 4, 1, 0};
    struct ls_map_def counter = {1, 4, 32, 256, 0};
    uint32_t key = 0;
    uint64_t value[4] = {1, 2, 3, 4};
    uint64_t first = ls_map_reloc(0, (const uint8_t *)&output, sizeof output,
                                  "old_output", 0, sizeof output);
    struct ls_map_set *set = ls_map_current();
    if (!set || first != 0 || !set->m[0].is_ring)
        return 2;
    assert(!ls_map_enter());
    assert(ls_map_reset_shapes() == -1); /* No reset beneath an active call. */
    ls_map_leave();
    assert(!ls_map_reset_shapes());
    uint64_t next = ls_map_reloc(0, (const uint8_t *)&counter, sizeof counter,
                                 "new_counter", 0, sizeof counter);
    ls_map_reloc(0, (const uint8_t *)&output, sizeof output,
                 "new_output", 0, sizeof output);
    set = ls_map_current();
    struct ls_map *map = ls_map_get(set, next);
    if (!map)
        return 2;
    int result = ls_map_update(map, (const uint8_t *)&key, (const uint8_t *)value);
    printf("{\"index\":%llu,\"registered_type\":%u,\"storage_is_ring\":%u,"
           "\"update_result\":%d,\"passed\":%s}\n",
           (unsigned long long)(next & 255u), g_ls_shapes[next & 255u].type, map->is_ring,
           result, result == 0 ? "true" : "false");
    assert(ls_map_get(set, first) == NULL); /* Old VM reference cannot alias. */
    if (result == 0) {
        uint64_t *found = ls_map_lookup(map, (const uint8_t *)&key);
        assert(found && !memcmp(found, value, sizeof value));
        /* Same layout and name, new generation: no inherited values. */
        assert(!ls_map_reset_shapes());
        uint64_t replacement = ls_map_reloc(0, (const uint8_t *)&counter, sizeof counter,
                                           "new_counter", 0, sizeof counter);
        set = ls_map_current();
        assert(ls_map_get(set, next) == NULL);
        assert(!ls_map_lookup(ls_map_get(set, replacement), (const uint8_t *)&key));
        assert(ls_map_update(ls_map_get(set, replacement), (const uint8_t *)&key,
                             (const uint8_t *)value) == 0);
    }
    return result == 0 ? 0 : 1;
}

/* Two retained TLS map sets across 100 registry replacements. */
#define LS_MAP_GLUE_IMPL
#include "ls_map_glue.h"
#include <assert.h>
#include <pthread.h>

static pthread_barrier_t barrier;
static uint64_t handle;

static void
sync_threads(void)
{
    int rc = pthread_barrier_wait(&barrier);
    assert(rc == 0 || rc == PTHREAD_BARRIER_SERIAL_THREAD);
}

static void *
reader(void *argument)
{
    uint64_t old_handle = UINT64_MAX;
    uint32_t key = 0;
    uint64_t value = (uint64_t)(uintptr_t)argument;
    for (unsigned round = 0; round < 100; round++) {
        sync_threads();
        assert(!ls_map_enter());
        struct ls_map_set *set = ls_map_current();
        struct ls_map *map = ls_map_get(set, handle);
        assert(map && !map->is_ring);
        assert(ls_map_get(set, old_handle) == NULL);
        assert(!ls_map_lookup(map, (uint8_t *)&key));
        assert(!ls_map_update(map, (uint8_t *)&key, (uint8_t *)&value));
        sync_threads(); /* Hold the reader guard while the writer tries reset. */
        sync_threads();
        assert(*(uint64_t *)ls_map_lookup(map, (uint8_t *)&key) == value);
        old_handle = handle;
        ls_map_leave();
        sync_threads();
    }
    assert(!munmap(g_ls_maps, sizeof *g_ls_maps));
    g_ls_maps = NULL;
    return NULL;
}

int
main(void)
{
    pthread_t threads[2] = {0};
    struct ls_map_def shape = {1, 4, 8, 1, 0};
    assert(!pthread_barrier_init(&barrier, NULL, 3));
    for (unsigned i = 0; i < 2; i++)
        assert(!pthread_create(&threads[i], NULL, reader, (void *)(uintptr_t)(i + 1)));
    for (unsigned round = 0; round < 100; round++) {
        assert(!ls_map_reset_shapes());
        shape.max_entries = round % 3 + 1;
        handle = ls_map_reloc(NULL, (uint8_t *)&shape, sizeof shape,
                              "thread_counter", 0, sizeof shape);
        assert(!g_ls_config.load_error);
        sync_threads();
        sync_threads();
        uint64_t generation = atomic_load(&g_ls_map_registry.generation);
        assert(ls_map_reset_shapes() == -1);
        assert(atomic_load(&g_ls_map_registry.generation) == generation);
        sync_threads();
        sync_threads();
    }
    for (unsigned i = 0; i < 2; i++) assert(!pthread_join(threads[i], NULL));
    assert(!pthread_barrier_destroy(&barrier));
    puts("PASS: 2 threads, 100 replacements; stale refs refused, fresh private values, busy reset refused");
    return 0;
}

/* Use the real output bridge. Check its result against a consumed record and
 * an observed full-ring drop. The cached pre-fix execution returned 1.
 */
#include "ls_tp_emit.c"

enum ls_verdict ls_vm_call(int slot, void *ctx, size_t len)
{
    (void)slot; (void)ctx; (void)len;
    abort(); /* This test must never enter the VM dispatch path. */
}

int main(void)
{
    g_tp_seg = calloc(1, LS_TP_SEG_SZ);
    if (!g_tp_seg)
        return 2;
    g_tp_seg_tried = 1;
    g_tp_seg->n_rings = 1;
    g_tp_seg->ring_stride = LS_TP_STRIDE;
    struct ls_ring *ring = ls_tp_seg_ring(g_tp_seg, 0);
    ls_ring_init(ring, LS_TP_RING_BYTES, LS_RING_STREAM);
    uint64_t payload = 42, received = 0;
    struct ls_rec header;
    int delivered = ls_tp_publish_raw(5, &payload, sizeof payload);
    int length = ls_ring_consume(ring, &header, &received, sizeof received);
    if (length != (int)sizeof payload || received != payload)
        return 2;
    int dropped = 99;
    for (unsigned i = 0; i < 2000 && !atomic_load(&ring->drops); i++)
        dropped = ls_tp_publish_raw(5, &payload, sizeof payload);
    int passed = delivered == 0 && dropped == -1 && atomic_load(&ring->drops) == 1;
    printf("{\"delivered_result\":%d,\"consumed_bytes\":%d,"
           "\"dropped_result\":%d,\"drops\":%llu,\"passed\":%s}\n",
           delivered, length, dropped, (unsigned long long)atomic_load(&ring->drops),
           passed ? "true" : "false");
    free(g_tp_seg);
    g_tp_seg = NULL;
    if (ls_tp_publish_raw(5, &payload, sizeof payload) != -1)
        return 2; /* Disabled output must not report delivery. */
    return passed ? 0 : 1;
}

/* check_glue_owner.c --- the owning TU, and the assertions.
 *
 * WHAT THIS EXISTS TO CATCH. On 2026-08-17 the five uBPF registrations that make
 * maps work lived only in the build box's copy of ls_vm.c and were never carried
 * back into the repo. Copying the repo over that tree deleted them. Nothing
 * failed: programs loaded, PREVAIL verified them, they ran, and every map lookup
 * returned NULL --- indistinguishable from a predicate that never matches. The
 * live "maps work" result had been produced by an earlier binary that still had
 * the calls.
 *
 * Two things had to change for that to be catchable, and both are tested here:
 *
 *   1. The five calls became ONE call, ls_map_glue_install(). A five-step
 *      sequence duplicated across two arm paths can be half-applied or half-lost.
 *   2. The glue's state stopped being `static` in a header. It was safe only
 *      because exactly one file happened to include it; the install function
 *      means two now do, and `static` would have given each its own array.
 *
 * The link itself is part of the test. Two TUs include the header, one defines
 * LS_MAP_GLUE_IMPL, and if both ever did the link fails on a duplicate symbol.
 */
#define LS_MAP_GLUE_IMPL 1
#include "ls_map_glue.h"

#include <stdio.h>
#include <string.h>
#include <assert.h>

extern unsigned user_nshapes(void);
extern int      user_install(void *vm);
extern char     calls[];
extern int      ncalls, fail_at;

int
owner_install(void *vm)
{
    return ls_map_glue_install((struct ubpf_vm *)vm);
}

static void
reset(void)
{
    calls[0] = 0;
    ncalls   = 0;
    fail_at  = -1;
}

int
main(void)
{
    struct { int unused; } fake_vm;
    int k;

    /* --- 1. ONE array, two TUs -------------------------------------------- */
    g_ls_shapes[0].key_size = 0xABCDu;
    assert(g_ls_shapes[0].key_size == 0xABCDu);
    assert(user_nshapes() == 0u);       /* reachable from the non-owning TU too */
    printf("ok    two TUs share ONE g_ls_shapes (a static in the header gave each its own)\n");

    /* --- 2. all five registrations, relocation FIRST ----------------------
     * Order is not cosmetic. ubpf_load_elf_ex walks the maps section and asks
     * the relocation callback there; registered afterwards it is never asked,
     * every `lddw` keeps the zero clang emitted, and every helper receives
     * map=0. That program loads, verifies and runs with maps always empty. */
    reset();
    assert(owner_install(&fake_vm) == 0);
    assert(strcmp(calls, "reloc bounds h1 h2 h3 h4 h5 h25 ") == 0);
    printf("ok    install order: %s\n", calls);

    /* --- 3. the non-owning TU installs identically ------------------------- */
    reset();
    assert(user_install(&fake_vm) == 0);
    assert(strcmp(calls, "reloc bounds h1 h2 h3 h4 h5 h25 ") == 0);
    printf("ok    non-owning TU installs identically (no divergence by includer)\n");

    /* --- 4. a NULL vm is refused before anything is registered ------------- */
    reset();
    assert(owner_install(NULL) == -1 && ncalls == 0);
    printf("ok    NULL vm refused, nothing registered\n");

    /* --- 5. all-or-nothing ------------------------------------------------
     * A VM with relocation but no bounds check resolves map indices and then
     * refuses every read of a value; one with helpers but no relocation hands
     * every helper map=0. Both look like a working feature. So any single
     * refusal must fail the whole install. */
    /* EIGHT registrations now: reloc, bounds, and helpers 1/2/3/4/5/25. The clock and the
     * ringbuf helper are part of the same all-or-nothing set on purpose --- a VM that
     * resolved a ringbuf map and then had no helper to emit through would give a program
     * that verifies, runs, and silently drops everything it tried to publish. */
    for (k = 0; k < 8; k++) {
        reset();
        fail_at = k;
        assert(owner_install(&fake_vm) == -1);
    }
    printf("ok    install is all-or-nothing at each of the 8 registrations\n");

    /* --- 6. MAP IDENTITY IS THE NAME, NOT THE SHAPE -----------------------
     * The dedup used to compare (key_size, value_size, max_entries) only. Correct
     * within one program --- clang emits one relocation per reference --- and
     * wrong across programs, because the shape table is process-global. Two
     * unrelated programs each declaring a 4/8/64 map got the SAME index and so
     * the same per-thread storage, each reading the other's counts as its own.
     * Silent: shared state looks like a counter running high.
     *
     * These build a maps section by hand and call the relocation callback the way
     * ubpf_load_elf_ex does. What is asserted is mostly REFUSAL, because every
     * failure in this callback resolves to a plausible index rather than an
     * error. */
    {
        struct ls_map_def a = { LS_MAP_TYPE_HASH, 4u, 8u, 64u, 0u };
        struct ls_map_def b = { LS_MAP_TYPE_HASH, 8u, 8u, 64u, 0u };  /* same name,
                                                                       * other shape */
        unsigned char sec[3 * sizeof(struct ls_map_def)];
        const uint64_t REFUSED = (uint64_t)LS_MAP_MAX + 1u;
        char longname[LS_MAP_NAME_MAX + 8];
        uint64_t i0, i1;

        memcpy(sec + 0 * sizeof a, &a, sizeof a);
        memcpy(sec + 1 * sizeof a, &a, sizeof a);
        memcpy(sec + 2 * sizeof a, &b, sizeof b);

        ls_map_reset_shapes();
        assert(atomic_load(&g_ls_nshapes) == 0u);

        /* First reference to "rate" takes an index. */
        i0 = ls_map_reloc(NULL, sec, sizeof sec, "rate", 0, sizeof a);
        assert((i0 & 255u) < LS_MAP_MAX);

        /* Second reference to the SAME name and shape resolves to the SAME index
         * --- this is the within-program dedup, still required. */
        assert(ls_map_reloc(NULL, sec, sizeof sec, "rate", 0, sizeof a) == i0);

        /* THE FIX. An identically shaped map under a DIFFERENT name must get its
         * own index. Before the name key this returned i0 and the two programs
         * shared storage. */
        i1 = ls_map_reloc(NULL, sec, sizeof sec, "resets_seen",
                          1 * sizeof a, sizeof a);
        assert((i1 & 255u) < LS_MAP_MAX);
        assert(i1 != i0);

        /* Same name, DIFFERENT shape: refused, never shared. Two programs that
         * disagree about a shared map's layout would both write it. */
        assert(ls_map_reloc(NULL, sec, sizeof sec, "rate",
                            2 * sizeof a, sizeof b) == REFUSED);

        /* No name at all: identity is undecidable, so neither sharing nor
         * privacy can be chosen correctly. Refuse rather than guess. */
        assert(ls_map_reloc(NULL, sec, sizeof sec, NULL, 0, sizeof a) == REFUSED);
        assert(ls_map_reloc(NULL, sec, sizeof sec, "",   0, sizeof a) == REFUSED);

        /* A name that would not round-trip through the table is refused rather
         * than truncated --- truncation turns two distinct maps into one. */
        memset(longname, 'x', sizeof longname - 1);
        longname[sizeof longname - 1] = '\0';
        assert(ls_map_reloc(NULL, sec, sizeof sec, longname, 0, sizeof a) == REFUSED);

        /* Reset clears NAMES too. A name surviving at an index the next load
         * reuses would match a map it has nothing to do with --- which is the
         * aliasing this change removes, reintroduced by the reset path. */
        ls_map_reset_shapes();
        for (k = 0; k < (int)LS_MAP_MAX; k++)
            assert(g_ls_names[k][0] == '\0');

        printf("ok    map identity is the NAME: same name+shape shares, "
               "different name is private, name+other shape REFUSED\n");
    }

    /* --- 7. THE CLOCK ------------------------------------------------------
     * The most useful addition in the inventory, because without it a program cannot
     * express "N per second" and every threshold means "ever". Two properties matter: it
     * must not return 0 (a program comparing against 0 sees no elapsed time, so every
     * limiter opens), and it must not go backwards. */
    {
        uint64_t t1 = ls_h_ktime_get_ns(0, 0, 0, 0, 0);
        uint64_t t2 = ls_h_ktime_get_ns(0, 0, 0, 0, 0);
        assert(t1 != 0);
        assert(t2 >= t1);          /* MONOTONIC, so this cannot regress */
        printf("ok    bpf_ktime_get_ns non-zero and never regresses (MONOTONIC, not "
               "REALTIME --- a clock step must not open every limiter)\n");
    }

    /* --- 8. THE EMIT HELPER, and mostly its REFUSALS ------------------------
     * Every guard returns before touching the ring. The stub counts what gets through, so
     * "publish did not happen" is asserted rather than assumed. */
    {
        extern int ls_tp_publish_calls;
        extern unsigned long ls_tp_publish_len;
        const uint64_t REFUSED = (uint64_t)-1;
        struct ls_map_def rb = { LS_MAP_TYPE_PERF_EVENT_ARRAY, 4u, 4u, 16u, 0u };
        struct ls_map_def hs = { LS_MAP_TYPE_HASH, 4u, 8u, 64u, 0u };
        unsigned char sec[2 * sizeof(struct ls_map_def)];
        unsigned char payload[64];
        uint64_t ring_idx, hash_idx;

        memcpy(sec, &rb, sizeof rb);
        memcpy(sec + sizeof rb, &hs, sizeof hs);
        memset(payload, 0x5a, sizeof payload);

        ls_map_reset_shapes();
        g_ls_maps = 0;                 /* force this thread's storage to be rebuilt */
        g_ls_maps_failed = 0;

        /* A RINGBUF descriptor must be ADMITTED: key_size and value_size are 0, which the
         * hash checks correctly refuse, so it needs its own path. */
        ring_idx = ls_map_reloc(NULL, sec, sizeof sec, "ring", 0, sizeof rb);
        assert((ring_idx & 255u) < LS_MAP_MAX);
        hash_idx = ls_map_reloc(NULL, sec, sizeof sec, "counts", sizeof rb, sizeof hs);
        assert((hash_idx & 255u) < LS_MAP_MAX && hash_idx != ring_idx);

        ls_tp_publish_calls = 0;
        g_ls_cur_slot = 5;

        assert(ls_h_perf_event_output(0, ring_idx, 0, (uint64_t)(uintptr_t)payload, 0) == REFUSED);
        assert(ls_h_perf_event_output(0, ring_idx, 0, (uint64_t)(uintptr_t)payload, LS_RB_MAX_RECORD + 1) == REFUSED);
        assert(ls_h_perf_event_output(0, ring_idx, 0, 0, 8) == REFUSED);
        /* A HASH map is not a ring --- emitting through one would publish table bytes. */
        assert(ls_h_perf_event_output(0, hash_idx, 0, (uint64_t)(uintptr_t)payload, 8) == REFUSED);
        assert(ls_h_perf_event_output(0, LS_MAP_MAX + 5, 0, (uint64_t)(uintptr_t)payload, 8) == REFUSED);
        assert(ls_tp_publish_calls == 0);   /* not one of those reached the ring */

        /* No program running --- reached from anywhere else, refuse. */
        g_ls_cur_slot = -1;
        assert(ls_h_perf_event_output(0, ring_idx, 0, (uint64_t)(uintptr_t)payload, 8) == REFUSED);
        assert(ls_tp_publish_calls == 0);

        /* And the one case that SHOULD publish. */
        g_ls_cur_slot = 5;
        assert(ls_h_perf_event_output(0, ring_idx, 0, (uint64_t)(uintptr_t)payload, 32) == 0);
        assert(ls_tp_publish_calls == 1);
        assert(ls_tp_publish_len == 32);

        /* A hash operation on the RING slot must be an explicit no-op, not zero-size
         * arithmetic that happens to work out. */
        {
            struct ls_map *rm = ls_map_get(ls_map_current(), ring_idx);
            uint32_t key = 1; uint64_t val = 2;
            assert(rm != 0 && rm->is_ring);
            assert(ls_map_lookup(rm, (const uint8_t *)&key) == 0);
            assert(ls_map_update(rm, (const uint8_t *)&key, (const uint8_t *)&val) != 0);
            assert(ls_map_delete(rm, (const uint8_t *)&key) != 0);
        }
        printf("ok    bpf_ringbuf_output: 6 refusals (size 0, oversize, NULL, hash map, "
               "bad index, no program), 1 publish, hash ops on a ring refuse\n");
    }

    /* --- 9. bpf_probe_read, and it is almost entirely refusals ---------------
     * This is the helper that lets a program chase pointers itself, which is what removes
     * the per-hook ctx builder --- and therefore the rebuild --- from the critical path. Its
     * value rests entirely on refusing a bad address instead of faulting, so that is what
     * gets tested. A crash here would take the data plane with it. */
    {
        const uint64_t REFUSED = (uint64_t)-1;
        unsigned char dst[64];
        uint64_t src_ok = (uint64_t)(uintptr_t)&dst[32];   /* our own stack: mapped */

        memset(dst, 0, sizeof dst);
        dst[32] = 0xAB; dst[33] = 0xCD;

        /* the reading-works case, first, so a blanket-refuse implementation fails here */
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 2, src_ok, 0, 0) == 0);
        assert(dst[0] == 0xAB && dst[1] == 0xCD);

        /* NULL either side */
        assert(ls_h_probe_read(0, 8, src_ok, 0, 0) == REFUSED);
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 8, 0, 0, 0) == REFUSED);
        /* zero and over-cap sizes: refused, never clamped */
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 0, src_ok, 0, 0) == REFUSED);
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, LS_PROBE_READ_MAX + 1,
                               src_ok, 0, 0) == REFUSED);
        /* THE ONE THAT MATTERS: a wild pointer must be refused, not dereferenced. If the
         * range check is wrong this test does not fail, it segfaults --- which is itself
         * the signal. */
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 8,
                               0x0000dead0000beefULL, 0, 0) == REFUSED);
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 8, 0x1000ULL, 0, 0) == REFUSED);
        /* address arithmetic that wraps */
        assert(ls_h_probe_read((uint64_t)(uintptr_t)dst, 64,
                               0xffffffffffffffe0ULL, 0, 0) == REFUSED);

        /* A read must sit inside ONE mapping. Straddling the end of the highest range is
         * the accident this catches --- a pointer that walked off the end of something. */
        {
            struct ls_ranges *rs = ls_ranges_current(1);
            assert(rs != 0 && rs->n > 0);
            assert(ls_addr_readable(rs->r[rs->n - 1].hi - 4, 64) == 0);
            assert(ls_addr_readable(rs->r[0].lo, 1) == 1);
            printf("ok    /proc/self/maps parsed: %u readable range(s)\n", rs->n);
        }
        printf("ok    bpf_probe_read: reads what is mapped, REFUSES null, zero, over-cap, "
               "wild, low, wrapping, and straddling\n");
    }

    printf("ok    check_glue: 36 assertions\n");
    return 0;
}

